    static readonly List<FixedMod> RetiredClothingAndMap=Safe.Json.Deserialize<List<FixedMod>>(@"[{""Id"":""mod-17811"",""Immutable"":false,""Dependencies"":[],""Files"":[{""Path"":""archive/pc/mod/RealisticMap8K.archive"",""Size"":64110592,""Sha256"":""78e2d9015912c99be8e7b354ba4365c45b4cf47bb8c1ac0e420a260be5fc9aba""}]},{""Id"":""mod-18084"",""Immutable"":false,""Dependencies"":[""ArchiveXL"",""TweakXL"",""mod-6945"",""CET"",""mod-14210"",""mod-10437""],""Files"":[{""Path"":""archive/pc/mod/rm_legs_ripper.archive"",""Size"":48381952,""Sha256"":""c24bacb008671c0c5abe66acb71362519c754fa3e07298f3f0ec72f818e76bf6""},{""Path"":""archive/pc/mod/rm_legs_ripper.xl"",""Size"":9200,""Sha256"":""3f5afa9125de45965af5db1be5a273a8139e62fbca7ef9be77dea406d9fa2613""},{""Path"":""r6/tweaks/raem/rm_legs_ripper.yaml"",""Size"":3939,""Sha256"":""728c3c291e3be8179a09e5b7d6bf7bd586b14b72d7467372b728e0ad3bf84357""},{""Path"":""r6/tweaks/raem/rm_legs_ripper_belt.yaml"",""Size"":2205,""Sha256"":""773afc2313304d9f9c762f8676af5bd8ca516769e92eba6180e66962b3add3f6""}]}]");
    // These recipes validate protected receipts from releases that offered these files.
    static readonly Lazy<FixedCatalog> SnapshotRecipes=new Lazy<FixedCatalog>(()=>{
        using(var reader=new StreamReader(typeof(HistoricalReceipts).Assembly.GetManifestResourceStream("CyberpunkCoop.legacy-snapshots.json")))
            return Safe.Json.Deserialize<FixedCatalog>(reader.ReadToEnd());
    });
    internal static FixedCatalog CatalogForSnapshot(FixedCatalog catalog,InstalledSnapshotManifest manifest){
        catalog=NightCoopRelease.CatalogForReceipt(catalog,manifest);
        if(catalog==null||catalog.Id!=CatalogId||manifest==null||manifest.Game!="cyberpunk2077"||manifest.List==null||manifest.List.Mods==null)
            return catalog;
        var variants=manifest.List.Mods.Where(mod=>mod!=null&&mod.Variants!=null)
            .SelectMany(mod=>mod.Variants).Where(variant=>variant!=null).ToLookup(variant=>variant.CyberpunkId,StringComparer.Ordinal);
        var known=SnapshotRecipes.Value;
        var replacements=known.Packages.Where(recipe=>variants[recipe.Id].Any(variant=>
            recipe.Id=="mod-12637"?MatchesLegacyAtelier(manifest,recipe,variant):
            recipe.Id!=EquipmentExOptions.ModId?!catalog.Packages.Any(current=>current.Id==recipe.Id):
            variant.Id==EquipmentExOptions.WeaveId&&variant.CyberpunkVariant==null&&variant.Sources!=null&&
            variant.Sources.SequenceEqual(recipe.Assets.Select(asset=>asset.Url),StringComparer.Ordinal))).ToDictionary(recipe=>recipe.Id);
        if(replacements.Count==0)return catalog;
        return new FixedCatalog{
            Schema=catalog.Schema,Id=catalog.Id,GameVersion=catalog.GameVersion,GameFileVersion=catalog.GameFileVersion,Excluded=catalog.Excluded,
            Packages=catalog.Packages.Where(recipe=>!replacements.ContainsKey(recipe.Id)).Concat(replacements.Values).ToList(),
            Defaults=(catalog.Defaults??new List<FixedDefault>()).Concat(known.Defaults.Where(item=>replacements.ContainsKey(item.ModId))).ToList()
        };
    }
    static bool MatchesLegacyAtelier(InstalledSnapshotManifest manifest,FixedMod recipe,GeneralModVariant variant){
        if(manifest.Files==null||variant.InstallRoutes==null||variant.InstallRoutes.Count!=0)return false;
        string owner=recipe.Id+"/"+variant.Id;
        var files=manifest.Files.Where(file=>file!=null&&file.Kind=="file"&&file.Owners!=null&&file.Owners.Contains(owner)).ToArray();
        return files.Length==recipe.Files.Count&&recipe.Files.All(known=>files.Any(file=>
            file.Path==known.Path&&file.Size==known.Size&&file.Sha256==known.Sha256));
    }

    internal static IEnumerable<FixedMod> CleanupRecipes(FixedCatalog catalog) {
        if(catalog.Id!=CatalogId)return Enumerable.Empty<FixedMod>();
        return SnapshotRecipes.Value.Packages.Concat(new[]{retiredHotline}).Concat(RetiredClothingAndMap).Where(mod=>!mod.Immutable);
    }

    internal static IEnumerable<ModFileAnchor> CleanupAnchors(FixedCatalog catalog) {
        return CleanupRecipes(catalog).SelectMany(mod=>mod.Files.Select(file=>new ModFileAnchor{Owner=mod.Id,Path=file.Path,Hash=file.Sha256}));
    }

    internal static List<FixedMod> Expand(FixedCatalog catalog,IEnumerable<string> ids){
        var result=new List<FixedMod>();var done=new HashSet<string>();var visiting=new HashSet<string>();
        Action<string> visit=null;visit=id=>{
            if(done.Contains(id))return;if(!visiting.Add(id))throw new IOException("Ciclo no histórico de instalação.");
            var current=catalog.Packages.SingleOrDefault(m=>m.Id==id);
            var prior=catalog.Id==CatalogId?(id==RetiredPackEntries.HotlineId?retiredHotline:(Recipes.SingleOrDefault(m=>m.Id==id)??RetiredClothingAndMap.SingleOrDefault(m=>m.Id==id)??SnapshotRecipes.Value.Packages.SingleOrDefault(m=>m.Id==id))):null;
            if(current==null&&prior==null)throw new IOException("Mod do recibo não reconhecido no catálogo ou histórico: "+id);
            foreach(string dependency in (current??prior).Dependencies)visit(dependency);
            var recipe=Safe.Json.Deserialize<FixedMod>(Safe.Json.Serialize(current??prior));
            if(prior!=null&&current!=null)recipe.Files.AddRange(prior.Files);
            recipe.Immutable|=prior!=null&&prior.Immutable;
            result.Add(recipe);visiting.Remove(id);done.Add(id);
        };
        foreach(string id in ids)visit(id);return result;
    }
